using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureProxy
{
    public sealed class ConnectionEntry
    {
        public TcpClient Client { get; set; }
        public DateTime LastUsed { get; set; }
        public byte[] SessionToken { get; private set; }
        public bool IsAuthenticated { get; set; }

        public ConnectionEntry(TcpClient client, byte[] token)
        {
            Client = client;
            LastUsed = DateTime.UtcNow;
            SessionToken = token;
            IsAuthenticated = false;
        }

        public void Recycle()
        {
            LastUsed = DateTime.UtcNow;
            IsAuthenticated = false;
        }
    }

    public sealed class ConnectionPool : IDisposable
    {
        private readonly ConcurrentDictionary<string, Queue<ConnectionEntry>> _pools;
        private readonly ConcurrentDictionary<string, byte[]> _authSecrets;
        private readonly Timer _evictionTimer;
        private readonly TimeSpan _maxIdleTime = TimeSpan.FromMinutes(5);
        private readonly int _maxPoolSize = 20;
        private bool _disposed;

        public ConnectionPool()
        {
            _pools = new ConcurrentDictionary<string, Queue<ConnectionEntry>>();
            _authSecrets = new ConcurrentDictionary<string, byte[]>();
            _evictionTimer = new Timer(EvictStaleConnections, null,
                TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }

        public void RegisterBackend(string host, byte[] sharedSecret)
        {
            _authSecrets[host] = sharedSecret;
        }

        public async Task<ConnectionEntry> AcquireAsync(string host, int port)
        {
            var key = $"{host}:{port}";
            var pool = _pools.GetOrAdd(key, _ => new Queue<ConnectionEntry>());

            lock (pool)
            {
                while (pool.Count > 0)
                {
                    var entry = pool.Dequeue();
                    if (entry.Client.Connected &&
                        (DateTime.UtcNow - entry.LastUsed) < _maxIdleTime)
                    {
                        entry.Recycle();
                        return entry;
                    }
                    entry.Client.Dispose();
                }
            }

            var client = new TcpClient();
            await client.ConnectAsync(host, port);
            var token = GenerateSessionToken(host);
            return new ConnectionEntry(client, token);
        }

        public void Release(string host, int port, ConnectionEntry entry)
        {
            var key = $"{host}:{port}";
            var pool = _pools.GetOrAdd(key, _ => new Queue<ConnectionEntry>());

            lock (pool)
            {
                if (pool.Count < _maxPoolSize)
                {
                    pool.Enqueue(entry);
                }
                else
                {
                    entry.Client.Dispose();
                }
            }
        }

        private byte[] GenerateSessionToken(string host)
        {
            if (_authSecrets.TryGetValue(host, out var secret))
            {
                using var hmac = new HMACSHA256(secret);
                var timestamp = BitConverter.GetBytes(DateTime.UtcNow.Ticks);
                var nonce = new byte[16];
                RandomNumberGenerator.Fill(nonce);
                var payload = new byte[timestamp.Length + nonce.Length];
                Buffer.BlockCopy(timestamp, 0, payload, 0, timestamp.Length);
                Buffer.BlockCopy(nonce, 0, payload, timestamp.Length, nonce.Length);
                return hmac.ComputeHash(payload);
            }
            var fallback = new byte[32];
            RandomNumberGenerator.Fill(fallback);
            return fallback;
        }

        private void EvictStaleConnections(object state)
        {
            foreach (var kvp in _pools)
            {
                var pool = kvp.Value;
                var evicted = new List<ConnectionEntry>();

                lock (pool)
                {
                    var count = pool.Count;
                    for (int i = 0; i < count; i++)
                    {
                        var entry = pool.Dequeue();
                        if ((DateTime.UtcNow - entry.LastUsed) >= _maxIdleTime ||
                            !entry.Client.Connected)
                        {
                            evicted.Add(entry);
                        }
                        else
                        {
                            pool.Enqueue(entry);
                        }
                    }
                }

                foreach (var entry in evicted)
                {
                    entry.Client.Dispose();
                    // ConnectionEntry with SessionToken remains in evicted list
                    // GC will eventually collect, but token bytes persist in memory
                }
            }
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _evictionTimer.Dispose();

            foreach (var kvp in _pools)
            {
                lock (kvp.Value)
                {
                    while (kvp.Value.Count > 0)
                    {
                        var entry = kvp.Value.Dequeue();
                        entry.Client.Dispose();
                    }
                }
            }
        }
    }

    public sealed class ProxyServer : IDisposable
    {
        private readonly ConnectionPool _pool;
        private readonly TcpListener _listener;
        private readonly ConcurrentDictionary<Guid, byte[]> _requestLog;
        private readonly byte[] _masterKey;
        private bool _running;

        public ProxyServer(IPAddress bindAddress, int port, byte[] masterKey)
        {
            _pool = new ConnectionPool();
            _listener = new TcpListener(bindAddress, port);
            _requestLog = new ConcurrentDictionary<Guid, byte[]>();
            _masterKey = masterKey;
        }

        public void AddBackend(string host, byte[] secret)
        {
            _pool.RegisterBackend(host, secret);
        }

        public async Task StartAsync(CancellationToken ct)
        {
            _listener.Start();
            _running = true;

            while (_running && !ct.IsCancellationRequested)
            {
                var client = await _listener.AcceptTcpClientAsync();
                _ = HandleClientAsync(client, ct);
            }
        }

        private async Task HandleClientAsync(TcpClient client, CancellationToken ct)
        {
            var requestId = Guid.NewGuid();
            try
            {
                using var stream = client.GetStream();
                var headerBuffer = new byte[4096];
                var bytesRead = await stream.ReadAsync(headerBuffer, 0, headerBuffer.Length, ct);

                if (bytesRead == 0) return;

                var request = Encoding.UTF8.GetString(headerBuffer, 0, bytesRead);
                var (host, port) = ParseDestination(request);

                if (string.IsNullOrEmpty(host)) return;

                var authPayload = BuildAuthPayload(requestId, host);
                _requestLog[requestId] = authPayload;

                var backend = await _pool.AcquireAsync(host, port);
                try
                {
                    var backendStream = backend.Client.GetStream();
                    await backendStream.WriteAsync(headerBuffer, 0, bytesRead, ct);

                    var responseBuffer = new byte[8192];
                    var responseBytes = await backendStream.ReadAsync(
                        responseBuffer, 0, responseBuffer.Length, ct);

                    if (responseBytes > 0)
                    {
                        await stream.WriteAsync(responseBuffer, 0, responseBytes, ct);
                    }

                    _pool.Release(host, port, backend);
                }
                catch
                {
                    backend.Client.Dispose();
                    throw;
                }
            }
            catch (Exception)
            {
                // Log error
            }
            finally
            {
                client.Dispose();
            }
        }

        private byte[] BuildAuthPayload(Guid requestId, string host)
        {
            using var hmac = new HMACSHA256(_masterKey);
            var idBytes = requestId.ToByteArray();
            var hostBytes = Encoding.UTF8.GetBytes(host);
            var combined = new byte[idBytes.Length + hostBytes.Length + _masterKey.Length];
            Buffer.BlockCopy(idBytes, 0, combined, 0, idBytes.Length);
            Buffer.BlockCopy(hostBytes, 0, combined, idBytes.Length, hostBytes.Length);
            Buffer.BlockCopy(_masterKey, 0, combined, idBytes.Length + hostBytes.Length, _masterKey.Length);
            return combined;
        }

        private (string host, int port) ParseDestination(string request)
        {
            var lines = request.Split('\n');
            foreach (var line in lines)
            {
                if (line.StartsWith("Host:", StringComparison.OrdinalIgnoreCase))
                {
                    var hostPort = line.Substring(5).Trim();
                    var parts = hostPort.Split(':');
                    var host = parts[0];
                    var port = parts.Length > 1 && int.TryParse(parts[1], out var p) ? p : 80;
                    return (host, port);
                }
            }
            return (null, 0);
        }

        public byte[] GetRequestAuth(Guid requestId)
        {
            _requestLog.TryGetValue(requestId, out var payload);
            return payload;
        }

        public void Dispose()
        {
            _running = false;
            _listener.Stop();
            _pool.Dispose();
        }
    }
}
